"""Demo: the mean of the committee werewolf-count equals t*k/n exactly."""
from fractions import Fraction
from math import comb

def hyp_mean_direct(n: int, k: int, t: int) -> Fraction:
    """Naive mean sum_j j * C(k,j) C(n-k,t-j) / C(n,t)."""
    D = comb(n, t)
    return sum(Fraction(j * comb(k, j) * comb(n - k, t - j), D) for j in range(t + 1))

def hyp_mean_formula(n: int, k: int, t: int) -> Fraction:
    """Closed form from the bridge: t*k/n."""
    return Fraction(t * k, n)

if __name__ == "__main__":
    for (n, k, t) in [(10, 3, 4), (20, 7, 6), (52, 13, 5)]:
        assert hyp_mean_direct(n, k, t) == hyp_mean_formula(n, k, t)
        print(f"n={n} k={k} t={t}: mean = {hyp_mean_formula(n, k, t)}")

"""Demo: single random suspect is a werewolf with prior probability k/n."""
from fractions import Fraction
from math import comb

def suspect_werewolf_prob(n: int, k: int) -> Fraction:
    """Mean of the t=1 committee count = P(suspect is werewolf)."""
    return sum(Fraction(j * comb(k, j) * comb(n - k, 1 - j), comb(n, 1))
               for j in range(2))

if __name__ == "__main__":
    for (n, k) in [(5, 1), (7, 2), (100, 20)]:
        p = suspect_werewolf_prob(n, k)
        assert p == Fraction(k, n)
        print(f"n={n} k={k}: P(werewolf) = {p} ~= {float(p):.4f}")

