from fractions import Fraction

def committee_mean(n: int, k: int, t: int) -> Fraction:
    """Expected number of werewolves in a random t-committee, as t*k/n.

    O(1) exact evaluation justified by Bridge 2 (absorption + Vandermonde),
    which proves this closed form equals the naive moment sum.
    """
    if n <= 0 or not (1 <= k <= n) or not (1 <= t <= n):
        raise ValueError("require 1 <= k <= n and 1 <= t <= n")
    return Fraction(t * k, n)

