from math import comb

def vandermonde_verify(n: int, k: int, t: int) -> bool:
    """Verify Vandermonde's convolution sum_j C(k,j) C(n-k,t-j) = C(n,t).

    Exact integer arithmetic; O(t) multiplications. Certifies the identity
    for concrete parameters and doubles as a normalization self-test.
    """
    if not (k <= n):
        raise ValueError("require k <= n")
    lhs = sum(comb(k, j) * comb(n - k, t - j) for j in range(t + 1))
    return lhs == comb(n, t)

